        "slug": "the-hydraulic-impedance",
        "formalismMode": "equation",
        "anchor": "Inside the physiology laboratory at University College London in the spring of 1914, Ernest Starling observed an isolated canine heart. The organ sat mounted within a scaffold of glass cannulae, brass pressure reservoirs, and mercury manometers.",
        "exitFact": "That elastic expansion stores kinetic energy as wall tension and recoils during diastole to keep blood moving smoothly through peripheral tissue beds."
