        "slug": "the-countercurrent-multiplexer",
        "formalismMode": "diagram",
        "anchor": "No biological membrane in the animal kingdom possesses a molecular pump capable of driving neutral water molecules uphill against an osmotic gradient. Yet human kidneys routinely excrete urine four times more concentrated than blood plasma.",
