        "formalismMode": "equation",
        "anchor": "Severed from all neural connections in an oxygenated surgical bath, or transplanted into a recipient's chest, the human heart beats at an intrinsic rhythm of 100 to 110 contractions per minute. Yet a healthy adult sitting quietly in a chair exhibits a resting pulse of 60 beats per minute.",
