        "formalismMode": "equation",
        "anchor": "When pure actin filaments and pure myosin filaments are extracted from rabbit skeletal muscle and mixed in a glass beaker with adenosine triphosphate (ATP), the proteins precipitate into an immediate, irreversible contraction. In 1942 at the University of Szeged, Albert Szent-Györgyi had demonstrated that extracted actomyosin threads contract violently upon contact with ATP.",
