        "anchor": "A single photon of green light at a wavelength of 500 nanometers carries an energy quantum of roughly $2.48\\text{ electron-volts}$, or $4 \\times 10^{-19}\\text{ Joules}$. That energy is fifteen orders of magnitude smaller than the kinetic energy of a falling snowflake.",
        "exitFact": "Hundreds of membrane channels snap shut, blocking $10^7$ sodium ions from entering and hyperpolarizing the cell membrane to slow its synaptic glutamate release onto downstream bipolar neurons."
