        "slug": "the-thermal-core",
        "formalismMode": "equation",
        "anchor": "Inside the Physiological Institute of the University of Munich in 1894, Max Rubner sealed a small experimental dog inside a double-walled copper chamber submerged in an insulated water bath. Trained under Carl von Voit, Rubner had spent a decade building the world's first high-precision animal respiration calorimeter to settle the central dispute of nineteenth-century biology.",
        "exitFact": "Secreting up to 2 liters of hypotonic fluid per hour, evaporation sheds over 1,300 watts of thermal load through phase change."
