        "subtitle": "Alan Hodgkin, Andrew Huxley, and the Axonal Voltage Clamp in Plymouth",
        "slug": "the-electrochemical-gate",
        "formalismMode": "diagram",
        "anchor": "Measuring nearly one millimeter in diameter, the giant axon of the Atlantic squid (*Loligo forbesii*) is one hundred times thicker than a mammalian motor nerve fiber. In 1939, it was the only nerve fiber known to science large enough to let an experimenter thread a glass capillary electrode straight down its intracellular core without tearing the outer membrane.",
        "exitFact": "That insulation forces the action potential to leap electrotonically between uninsulated nodes of Ranvier at velocities up to $120\\text{ meters per second}$."
