        "formalismMode": "equation",
        "anchor": "Arterial blood in a healthy human maintains a free hydrogen ion concentration ($[\\text{H}^+]$) of roughly $40\\text{ nanomoles per liter}$—one-millionth the concentration of blood sodium ions—corresponding to a pH of 7.40. Yet cellular metabolism pours roughly 15,000 millimoles of volatile carbonic acid and 70 millimoles of non-volatile sulfuric and phosphoric acids into the bloodstream every twenty-four hours.",
