        "anchor": "Constructed from germanium in 1947 at Bell Laboratories, the earliest transistors failed whenever the surrounding air grew hot. Germanium was easy to zone-refine and melted at a manageable $937^\\circ\\text{C}$, but its narrow electronic bandgap of $0.66\\text{ electron-volts}$ meant that warming a circuit above $70^\\circ\\text{C}$ thermally excited enough intrinsic electrons across the bandgap to flood the base region and short out the device.",
