        "exitFact": "Even so, the tiny ionic radius of $\\text{Li}^+$ ($0.076\\text{ nm}$) creates an intense local electric field that binds polar carbonate solvent molecules into a bulky solvation shell ($r_{\\text{solvated}} \\approx 0.4\\text{ nm}$); stripping that solvent shell at the graphite interface imposes a $50\\text{ kJ/mol}$ activation energy barrier that limits fast-charging speeds at freezing temperatures."
