        "slug": "introduction",
        "formalismMode": "introduction",
        "anchor": "On the morning of September 23, 1998, sixteen senior Wall Street executives gathered at the Federal Reserve Bank of New York to prevent the disorderly collapse of Long-Term Capital Management. Four months earlier, the Greenwich hedge fund—whose partners included two Nobel laureates in economics—controlled \\$4.72 billion in equity.",
        "exitFact": "Instead, they construct decision architectures that bound downside loss, preserve the option to wait when commitments cannot be reversed, update beliefs incrementally as noisy evidence arrives, and audit the missing data that survivorship conceals."
