        "slug": "the-absorbing-barrier",
        "formalismMode": "equation",
        "anchor": "On September 9, 1713, the Swiss mathematician Nicolaus Bernoulli mailed a letter from Basel to the French probabilist Pierre Rémond de Montmort in Paris containing a five-sentence gambling puzzle that paralyzed classical economics for three centuries. Suppose a casino offers a fair coin toss.",
        "exitFact": "After the Federal Reserve Bank of New York orchestrated a \\$3.625 billion rescue by fourteen banks on September 23, 1998, the exact bond convergence trades that bankrupted the partners turned profitable for the rescue consortium eighteen months later—inside a game from which the original equity holders had already been permanently erased."
