        "formalismMode": "equation",
        "anchor": "During the university spring break of April 1961, Massachusetts Institute of Technology mathematics instructor named Edward O. Thorp walked onto the casino floor of the Sands Hotel in Las Vegas with \\$10,000 in hundred-dollar bills provided by a New York backer named Manny Kimmel.",
        "exitFact": "Applying Kelly bet sizing in Las Vegas alongside their wives, Betty Shannon and Vivian Thorp, they multiplied their stakes until wire breaks retired the machine, after which Thorp applied fractional Kelly sizing to convertible bond arbitrage at Princeton Newport Partners, compounding capital at 19.1 percent annualized for twenty years without a losing quarter."
