        "exitFact": "On Wald's recommendation, the Army Air Forces reversed their blueprints, leaving the bullet-scarred fuselages unarmored and wrapping the pristine, unmarked engines and cockpits in heavy steel plate—a protocol that remained standard across American combat aircraft through the Korean and Vietnam wars."
