        "exitFact": "Sitting in a smoky tavern in Bijelo Polje in July 1935, the illiterate sixty-year-old butcher Avdo Međedović sang The Wedding of Smailagić Meho across five days onto Parry's twin turntable aluminum discs—generating 12,311 epic lines equal in length and structural complexity to Homer's Odyssey."
