        "exitFact": "Waitlisted by Cold War visa bans for nearly forty years, Knorozov finally stood atop the stone temples of Tikal and Palenque in 1990, reading aloud the dynastic names of Classic Maya kings that Western textbooks had once declared forever nameless."
