        "exitFact": "Still stored in seven hundred tin biscuit boxes at Oxford's Sackler Library, the five hundred thousand fragments dug from the Oxyrhynchus garbage mounds have restored lost poems of Sappho, satyr plays of Sophocles, early Christian gospels, and seventy percent of all surviving literary papyri on Earth."
