        "exitFact": "In 1983, Benjamin Libet's readiness-potential electroencephalography experiments at the University of California, San Francisco, confirmed James's 1890 model by demonstrating that premotor cortical activation begins hundreds of milliseconds before a subject reports a conscious decision to move, leaving conscious attention the exact veto role James had assigned it."
