        "slug": "the-squirrel-around-the-tree",
        "formalismMode": "diagram",
        "anchor": "William James's August 26, 1898 lecture at the University of California, Berkeley ('Philosophical Conceptions and Practical Results') and Lecture II of Pragmatism: A New Name for Some Old Ways of Thinking (delivered at the Lowell Institute in Boston in November–December 1906 and Columbia University in January 1907).",
        "exitFact": "Within eighteen months of its May 1907 publication, Pragmatism went through seven printings and turned a forgotten 1878 paper by Charles Sanders Peirce into the dominant philosophical movement of the twentieth-century Atlantic world."
