        "formalismMode": "ledger_or_list",
        "anchor": "Twelve-year-old Richard Feynman repairing vacuum-tube radios in Far Rockaway, Queens during the Great Depression by deducing why the loud hum faded, learning from his father Melville in the Catskill woods the difference between the name of a bird and its behavior, and caring for his wife Arline Greenbaum at the Albuquerque tuberculosis sanatorium until June 16, 1945.",
        "exitFact": "When Arline died of lymphatic tuberculosis at Presbyterian Sanatorium on June 16, 1945, the bedside alarm clock stopped at 9:22 p.m. because Feynman had repaired its loose dial earlier that evening and set it down on the nightstand."
