        "title": "Artificial Intelligence",
        "subtitle": "Mapping a Concept Through Its Surrounding Landscape",
        "slug": "introduction",
        "formalismMode": "introduction",
        "anchor": "For the first three decades of digital computing, engineers assumed that intelligence was a list of explicit instructions. If a mathematician could write down the axioms of geometry, a programmer could translate human expertise into logic gates.",
        "exitFact": "Mapping that surrounding landscape reveals both what statistical intelligence computes and why its sharpest failures occur."
