        "formalismMode": "diagram",
        "anchor": "Frank Rosenblatt demonstrating the Mark I Perceptron in July 1958 with 400 photocells and electric motors, followed by Marvin Minsky and Seymour Papert's 1969 MIT book proving a single linear hyperplane cannot solve the two-bit XOR problem.",
        "exitFact": "Adding a single hidden layer of just two rectified linear units folds the two-dimensional square along its diagonal, placing the matching XOR corners on the same side of a straight dividing line."
