        "slug": "high-dimensional-vector-embeddings",
        "formalismMode": "diagram",
        "anchor": "Linguist J. R. Firth's 1957 distributional dictum, Tomas Mikolov's 2013 Word2Vec vector arithmetic discovery at Google, and the high-dimensional almost-orthogonality law (Johnson-Lindenstrauss geometry).",
        "exitFact": "In three-dimensional room space you can place at most three mutually perpendicular axes at ninety degrees, but in a four-thousand-dimensional embedding space you can pack millions of directions that all sit between eighty-nine and ninety-one degrees apart."
