        "slug": "silicon-weights-versus-biological-brains",
        "formalismMode": "ledger_or_list",
        "anchor": "Francis Crick's 1989 Nature critique of backpropagation's biological implausibility and Mark Horowitz's 2014 Stanford silicon energy measurements showing that fetching a number from DRAM costs 640 picojoules while adding it costs 0.9 picojoules.",
        "exitFact": "While an adult human brain runs eighty-six billion neurons and a hundred trillion synapses on twenty watts—the power of a dim refrigerator bulb—training a single frontier language model consumes enough electricity to power a thousand households for a year."
