        "title": "The Lipid Bilayer and Ion Channels",
        "subtitle": "Hydrophobic Self-Assembly, Potassium Selectivity Filters, and the Resting Membrane Voltage",
        "slug": "the-lipid-bilayer-and-ion-channels",
        "formalismMode": "highlights",
        "anchor": "Evert Gorter and François Grendel extracted the lipids from a known count of red blood cells in 1925 and spread them across a Langmuir water trough. Compressing the floating film to a single molecular layer covered twice the surface area of the intact cells.",
